class CommandsPage extends StatefulWidget{const CommandsPage({super.key,required this.controller});final AppController controller;@override State<CommandsPage> createState()=>_CommandsPageState();}
class _CommandsPageState extends State<CommandsPage>{
  final _search=TextEditingController();@override void dispose(){_search.dispose();super.dispose();}
  @override Widget build(BuildContext context){final q=_search.text.trim().toLowerCase();final items=widget.controller.commands.where((c)=>q.isEmpty||c.title.toLowerCase().contains(q)||c.triggers.any((t)=>t.text.toLowerCase().contains(q))).toList();return Scaffold(backgroundColor:Colors.transparent,appBar:AppBar(title:const Text('الردود'),backgroundColor:Colors.transparent,actions:[IconButton(onPressed:widget.controller.refreshCommands,icon:const Icon(Icons.refresh_rounded))]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>_open(),icon:const Icon(Icons.add_rounded),label:const Text('إضافة رد')),body:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(16,4,16,12),child:TextField(controller:_search,onChanged:(_)=>setState((){}),decoration:const InputDecoration(prefixIcon:Icon(Icons.search_rounded),hintText:'بحث في الردود...'))),Expanded(child:RefreshIndicator(onRefresh:widget.controller.refreshCommands,child:items.isEmpty?ListView(children:const[SizedBox(height:140),Center(child:Text('لا توجد ردود مطابقة'))]):ListView.separated(padding:const EdgeInsets.fromLTRB(16,0,16,90),itemCount:items.length,separatorBuilder:(_,_)=>const SizedBox(height:10),itemBuilder:(context,index){final c=items[index];return Card(child:ListTile(onTap:()=>_open(c),leading:CircleAvatar(child:Icon(c.enabled?Icons.bolt_rounded:Icons.pause_rounded)),title:Text(c.title,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${c.scopeMode=='all'?'كل المجموعات':'${c.groupIds.length} مجموعة'}\n${c.responseContent.summary}',maxLines:3,overflow:TextOverflow.ellipsis),trailing:Switch(value:c.enabled,onChanged:(v)async{await widget.controller.api.updateCommand(c.id,{'enabled':v});await widget.controller.refreshCommands();})));})))]));}
